/* Casa Edel · intro (motion graphic). Una chispa rebota y va armando el logo letra por letra;
   al final el color sube desde abajo y la pantalla se levanta mostrando la web.
   Una vez por visita. Se saltea tocando la pantalla. Respeta "reducir movimiento". */
(function () {
  var KEY = 'ce-intro-v3', FORCE = /[?&]intro\b/.test(location.search);
  if (!FORCE) { try { if (sessionStorage.getItem(KEY)) return; sessionStorage.setItem(KEY, '1'); } catch (e) {} }
  var M = {"W":1100,"H":296,"SW":1962,"SH":184,"t":[{"n":"C","sx":0,"w":95,"h":132,"x":6,"y":124},{"n":"A1","sx":99,"w":90,"h":128,"x":81,"y":126},{"n":"S","sx":193,"w":94,"h":133,"x":172,"y":124},{"n":"A2","sx":291,"w":106,"h":160,"x":245,"y":126},{"n":"E1","sx":401,"w":235,"h":183,"x":339,"y":106},{"n":"D","sx":640,"w":225,"h":183,"x":533,"y":106},{"n":"E2","sx":869,"w":241,"h":184,"x":708,"y":106},{"n":"L","sx":1114,"w":185,"h":183,"x":909,"y":106},{"n":"e0","sx":1303,"w":157,"h":76,"x":277,"y":7},{"n":"e1","sx":1464,"w":164,"h":79,"x":424,"y":5},{"n":"e2","sx":1632,"w":37,"h":76,"x":578,"y":7},{"n":"e3","sx":1673,"w":88,"h":80,"x":606,"y":5},{"n":"e4","sx":1765,"w":65,"h":76,"x":681,"y":7},{"n":"e5","sx":1834,"w":54,"h":74,"x":741,"y":9},{"n":"e6","sx":1892,"w":66,"h":76,"x":796,"y":7}]}, SC = 'data:image/webp;base64,', SS = 'data:image/webp;base64,';
  var REDUCE = matchMedia('(prefers-reduced-motion: reduce)').matches;
  var BG = '#14288a', SPARK = '#ffd23f';

  // la página todavía no tiene <body> cuando corre este script: se tapa hasta montar la intro
  var pre = document.createElement('style');
  pre.textContent = 'html{background:' + BG + '}body>:not(#cei3){visibility:hidden}';
  document.head.appendChild(pre);

  var css = [
    '#cei3,#cei3 *{box-sizing:border-box;margin:0;padding:0;animation:none;transition:none}',
    '#cei3{position:fixed;inset:0;z-index:2147483000;background:' + BG + ';display:grid;place-items:center;overflow:hidden;cursor:pointer;-webkit-tap-highlight-color:transparent;will-change:transform}',
    '#cei3 .c3s{position:relative;height:auto;max-height:none;min-height:0;width:min(86vw,780px);aspect-ratio:' + M.W + '/' + M.H + ';will-change:transform}',
    '#cei3 .c3w{position:absolute;inset:0;will-change:transform}',
    '#cei3 .c3l{position:absolute;overflow:hidden;transform-origin:50% 100%;transform:scaleY(0)}',
    '#cei3 .c3l img{position:absolute;top:0;left:0;height:100%;max-width:none;user-select:none;-webkit-user-drag:none;pointer-events:none}',
    '#cei3 .c3l .c3c{clip-path:inset(100% 0 0 0)}',
    '#cei3 .c3k{position:absolute;left:0;top:0;width:max(9px,1.6%);aspect-ratio:1;margin:-0.8% 0 0 -0.8%;background:' + SPARK + ';border-radius:2px;box-shadow:0 0 10px ' + SPARK + ',0 0 22px rgba(255,210,63,.55);will-change:transform}',
    '#cei3 .c3b{position:absolute;left:0;top:0;width:max(4px,.8%);aspect-ratio:1;background:' + SPARK + ';border-radius:1px;box-shadow:0 0 8px ' + SPARK + ';opacity:0}',
    '#cei3 .c3x{position:absolute;right:max(16px,env(safe-area-inset-right));bottom:max(16px,env(safe-area-inset-bottom));font:600 12px/1 system-ui,-apple-system,sans-serif;letter-spacing:.08em;text-transform:uppercase;color:rgba(255,255,255,.75);background:transparent;border:1px solid rgba(255,255,255,.3);border-radius:999px;padding:9px 14px;cursor:pointer}'
  ].join('\n');

  function mount() {
    var st = document.createElement('style'); st.textContent = css; document.head.appendChild(st);
    var el = document.createElement('div'); el.id = 'cei3'; el.setAttribute('role', 'img'); el.setAttribute('aria-label', 'Electricidad Casa Edel');
    var stage = document.createElement('div'); stage.className = 'c3s';
    var word = document.createElement('div'); word.className = 'c3w';
    stage.appendChild(word); el.appendChild(stage);
    var skip = document.createElement('button'); skip.type = 'button'; skip.className = 'c3x'; skip.textContent = 'Saltar'; el.appendChild(skip);
    document.body.appendChild(el);
    if (pre.parentNode) pre.remove();
    var root = document.documentElement, prevOv = root.style.overflow; root.style.overflow = 'hidden';

    // letras: cada una con su silueta blanca y su versión en color encima
    var L = {};
    M.t.forEach(function (t) {
      var d = document.createElement('div'); d.className = 'c3l';
      d.style.left = (t.x / M.W * 100) + '%'; d.style.top = (t.y / M.H * 100) + '%';
      d.style.width = (t.w / M.W * 100) + '%'; d.style.height = (t.h / M.H * 100) + '%';
      [['c3i', SS], ['c3i c3c', SC]].forEach(function (p) {
        var i = document.createElement('img'); i.alt = ''; i.src = p[1]; i.className = p[0];
        i.style.width = (M.SW / t.w * 100) + '%'; i.style.height = (M.SH / t.h * 100) + '%'; i.style.left = (-t.sx / t.w * 100) + '%';
        d.appendChild(i);
      });
      word.appendChild(d); L[t.n] = { el: d, t: t };
    });

    var done = false, timers = [];
    function finish() {
      if (done) return; done = true; timers.forEach(clearTimeout);
      el.remove(); st.remove(); root.style.overflow = prevOv;
    }
    function after(ms, fn) { timers.push(setTimeout(fn, ms)); }

    // salida: la pantalla azul se levanta y deja ver la web
    var leaving = false;
    function leave(fast) {
      if (leaving) return; leaving = true;
      var D = fast ? 420 : 760;
      el.animate([{ transform: 'translateY(0)' }, { transform: 'translateY(-100%)' }], { duration: D, easing: 'cubic-bezier(.76,0,.24,1)', fill: 'forwards' });
      stage.animate([{ transform: 'none', opacity: 1 }, { transform: 'translateY(-18vh) scale(.92)', opacity: 0 }], { duration: D * .8, easing: 'cubic-bezier(.6,0,.4,1)', fill: 'forwards' });
      setTimeout(finish, D + 30);
    }
    el.addEventListener('click', function () { leave(true); });
    var loaded = document.readyState === 'complete';
    if (!loaded) addEventListener('load', function () { loaded = true; }, { once: true });
    function leaveWhenLoaded() { if (loaded) leave(); else { addEventListener('load', function () { leave(); }, { once: true }); after(3000, leave); } }

    if (REDUCE) {
      Object.keys(L).forEach(function (k) { L[k].el.style.transform = 'none'; L[k].el.querySelector('.c3c').style.clipPath = 'none'; });
      after(900, leaveWhenLoaded);
      return;
    }

    // medidas en píxeles del escenario
    var R = stage.getBoundingClientRect(), K = R.width / M.W;
    function P(x, y) { return [x * K, y * K]; }
    function box(n) { var t = L[n].t; return { cx: t.x + t.w / 2, top: t.y, bot: t.y + t.h, l: t.x, r: t.x + t.w }; }

    // la chispa vuela en parábolas (como una pelotita)
    var spark = document.createElement('div'); spark.className = 'c3k'; stage.appendChild(spark);
    var rot = 0, first = true;
    function hop(a, b, peak, dur, start) {
      var f = [], N = 14;
      for (var i = 0; i <= N; i++) {
        var s = i / N, x = a[0] + (b[0] - a[0]) * s;
        var top = Math.min(a[1], b[1]) - peak;            // altura máxima del salto
        var y = (1 - s) * (1 - s) * a[1] + 2 * (1 - s) * s * (2 * top - (a[1] + b[1]) / 2) + s * s * b[1];
        f.push({ transform: 'translate(' + x.toFixed(1) + 'px,' + y.toFixed(1) + 'px) rotate(' + (rot + s * 200).toFixed(0) + 'deg)' });
      }
      rot += 200;
      spark.animate(f, { duration: dur, delay: start, easing: 'linear', fill: first ? 'both' : 'forwards' }); first = false;
    }
    // una letra crece desde el piso, con rebote
    function grow(n, at, dur) {
      L[n].el.animate([
        { transform: 'scale(1.35,0)' }, { transform: 'scale(.92,1.12)', offset: .55 }, { transform: 'scale(1.04,.96)', offset: .8 }, { transform: 'none' }
      ], { duration: dur || 460, delay: at, easing: 'cubic-bezier(.2,.8,.3,1)', fill: 'both' });
    }
    // la palabra se va corriendo para quedar centrada mientras crece
    var shiftNow = 0;
    function shift(to, at, dur) {
      word.animate([{ transform: 'translateX(' + shiftNow + 'px)' }, { transform: 'translateX(' + to + 'px)' }], { duration: dur, delay: at, easing: 'cubic-bezier(.45,0,.2,1)', fill: 'forwards' });
      shiftNow = to;
    }

    var ORDER = ['L', 'E2', 'D', 'E1', 'A2', 'S', 'A1', 'C'];
    var baseY = Math.max.apply(null, ORDER.map(function (n) { return box(n).bot; })) - 6;
    var right = box('L').r, t = 0, prev = null, land = [];
    ORDER.forEach(function (n, i) {
      var b = box(n), left = b.l;
      var dx = (M.W / 2 - (left + right) / 2) * K * (i === 0 ? 1 : 1);
      var dur = i === 0 ? 560 : (i < 4 ? 300 : 230);
      var from = prev ? P(prev.cx, prev.top - 2) : [R.width * 1.15, -R.height * 1.2];
      from = [from[0] + (prev ? prevShift : 0), from[1]];
      var to = [b.cx * K + dx, baseY * K];
      hop(from, to, i === 0 ? R.height * .2 : R.height * (i < 4 ? .32 : .26), dur, t);
      if (i === 0) word.style.transform = 'translateX(' + dx + 'px)', shiftNow = dx; else shift(dx, t, dur);
      t += dur; grow(n, t - 20, i < 4 ? 460 : 400); land.push(t);
      prev = b; prevShift = dx;
    });
    var prevShift;

    // ELECTRICIDAD: la chispa sube y recorre la línea de arriba, las letras aparecen a su paso
    var E = M.t.filter(function (x) { return x.n.charAt(0) === 'e'; }).map(function (x) { return x.n; });
    var eTop = Math.min.apply(null, E.map(function (n) { return box(n).top; })), eBot = Math.max.apply(null, E.map(function (n) { return box(n).bot; }));
    var eL = box(E[0]).l, eR = box(E[E.length - 1]).r;
    var c = box('C');
    hop([c.cx * K, (c.top - 2) * K], [(eL - 20) * K, (eBot + eTop) / 2 * K], R.height * .25, 320, t);
    t += 320;
    var RUN = 460;
    spark.animate([
      { transform: 'translate(' + ((eL - 20) * K) + 'px,' + ((eBot + eTop) / 2 * K) + 'px) rotate(' + rot + 'deg)' },
      { transform: 'translate(' + ((eR + 24) * K) + 'px,' + ((eBot + eTop) / 2 * K) + 'px) rotate(' + (rot + 540) + 'deg)' }
    ], { duration: RUN, delay: t, easing: 'cubic-bezier(.4,0,.6,1)', fill: 'forwards' });
    rot += 540;
    E.forEach(function (n) {
      var b = box(n), at = t + RUN * ((b.cx - eL + 20) / (eR - eL + 44));
      L[n].el.animate([{ transform: 'translateY(40%) scale(.6)', opacity: 0 }, { transform: 'translateY(-12%) scale(1.06)', opacity: 1, offset: .6 }, { transform: 'none', opacity: 1 }],
        { duration: 360, delay: at - 60, easing: 'cubic-bezier(.2,.8,.3,1)', fill: 'both' });
    });
    t += RUN;

    // la chispa cae debajo del logo, rebota, y el color sube por las letras
    var groundY = (Math.max.apply(null, ORDER.map(function (n) { return box(n).bot; })) + 26) * K, midX = R.width / 2;
    hop([(eR + 24) * K, (eBot + eTop) / 2 * K], [midX, groundY], R.height * .18, 420, t);
    t += 420;
    spark.animate([{ opacity: 1, transform: 'translate(' + midX + 'px,' + groundY + 'px) scale(1)' }, { opacity: 0, transform: 'translate(' + midX + 'px,' + groundY + 'px) scale(3)' }], { duration: 260, delay: t, fill: 'forwards', easing: 'ease-out' });
    for (var k = 0; k < 10; k++) {
      var bit = document.createElement('div'); bit.className = 'c3b'; stage.appendChild(bit);
      var ang = Math.PI + (k / 9) * Math.PI, dist = R.height * (.18 + (k % 3) * .07);
      bit.animate([
        { opacity: 1, transform: 'translate(' + midX + 'px,' + groundY + 'px)' },
        { opacity: 0, transform: 'translate(' + (midX + Math.cos(ang) * dist * 1.8) + 'px,' + (groundY + Math.sin(ang) * dist) + 'px) rotate(180deg)' }
      ], { duration: 520, delay: t, easing: 'cubic-bezier(.1,.7,.3,1)', fill: 'forwards' });
    }
    ['C', 'A1', 'S', 'A2', 'E1', 'D', 'E2', 'L'].forEach(function (n, i) {
      L[n].el.querySelector('.c3c').animate([{ clipPath: 'inset(100% 0 0 0)' }, { clipPath: 'inset(0 0 0 0)' }], { duration: 480, delay: t + 40 + Math.abs(i - 3.5) * 45, easing: 'cubic-bezier(.3,.7,.2,1)', fill: 'both' });
    });
    stage.animate([{ transform: 'none' }, { transform: 'translateY(1.5%) scale(1.04,.96)' }, { transform: 'translateY(-1%) scale(.99,1.02)' }, { transform: 'none' }], { duration: 520, delay: t, easing: 'ease-out' });
    t += 700;

    after(t + 250, leaveWhenLoaded);
    after(9000, function () { leave(true); });
  }
  if (document.body) mount(); else document.addEventListener('DOMContentLoaded', mount, { once: true });
})();
